private Expression compileExpression(String xpath) {
    Expression expr;

    synchronized (compiled) {
        if (USE_SOFT_CACHE) {
            expr = null;
            SoftReference ref = (SoftReference) compiled.get(xpath);
            if (ref != null) {
                expr = (Expression) ref.get();
            }
        }
        else {
            expr = (Expression) compiled.get(xpath);
