    }

    if (expr != null) {
        return expr;
    }

    expr = (Expression) Parser.parseExpression(xpath, getCompiler());

    synchronized (compiled) {
        if (USE_SOFT_CACHE) {
            if (cleanupCount++ >= CLEANUP_THRESHOLD) {
                Iterator it = compiled.entrySet().iterator();
